import {trajectory3d} from './trajectory.mjs';
import {sensitivity} from './study.mjs';
import {survey,parseSurvey,example,hydraulics,telemetry,defaults,psi,rad} from './engine.mjs';
const $=id=>document.getElementById(id),fmt=(n,d=1)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
let current=[],view='section',oldUnit='m',hydState=null,baseline=null,sweepRows=[];
const value=id=>{if($(id).value.trim()==='')throw Error(`Fill in ${$(id).closest('label')?.textContent.trim()||id}.`);let n=Number($(id).value);if(!Number.isFinite(n))throw Error('Use finite numeric inputs.');return n;};
const metric=(label,n,unit,note='')=>`<div class="metric"><small>${label}</small><strong>${n}</strong><em>${unit}${note?' · '+note:''}</em></div>`;
function chart(series,{xlabel='',ylabel='',equal=false,down=false,zero=false,height=350}={}){
 let points=series.flatMap(s=>s.points),xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);
 let xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);if(zero)ymin=Math.min(0,ymin);
 if(xmax-xmin<1e-9){xmin-=1;xmax+=1;}if(ymax-ymin<1e-9){ymin-=1;ymax+=1;}
 let w=780,h=height,l=72,r=24,t=28,b=55,pw=w-l-r,ph=h-t-b;
 if(equal){let sx=(xmax-xmin)/pw,sy=(ymax-ymin)/ph,s=Math.max(sx,sy)*1.08,mx=(xmin+xmax)/2,my=(ymin+ymax)/2;xmin=mx-pw*s/2;xmax=mx+pw*s/2;ymin=my-ph*s/2;ymax=my+ph*s/2;}else{let pad=(ymax-ymin)*.08;ymin-=pad;ymax+=pad;}
 let X=x=>l+(x-xmin)/(xmax-xmin)*pw,Y=y=>t+(down?(y-ymin):(ymax-y))/(ymax-ymin)*ph;
 let s=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${ylabel} versus ${xlabel}"><rect x="${l}" y="${t}" width="${pw}" height="${ph}" fill="#f8fbfd"/>`;
 for(let i=0;i<=5;i++){let x=xmin+(xmax-xmin)*i/5,y=ymin+(ymax-ymin)*i/5;s+=`<path d="M${X(x)},${t}V${h-b} M${l},${Y(y)}H${w-r}" stroke="#dee8ef"/><text x="${X(x)}" y="${h-b+22}" text-anchor="middle">${fmt(x,Math.abs(xmax-xmin)<10?1:0)}</text><text x="${l-10}" y="${Y(y)+4}" text-anchor="end">${fmt(y,Math.abs(ymax-ymin)<10?1:0)}</text>`;}
 for(let line of series){s+=`<polyline points="${line.points.map(p=>X(p[0])+','+Y(p[1])).join(' ')}" fill="none" stroke="${line.color||'#1168b2'}" stroke-width="${line.width||2.5}" ${line.dash?'stroke-dasharray="6 5"':''}/>`;if(line.dots)for(let p of line.points)s+=`<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="3.2" fill="#1168b2"><title>${xlabel}: ${fmt(p[0],3)}; ${ylabel}: ${fmt(p[1],3)}</title></circle>`;}
 return s+`<text x="${l+pw/2}" y="${h-9}" text-anchor="middle">${xlabel}</text><text transform="translate(17,${t+ph/2}) rotate(-90)" text-anchor="middle">${ylabel}</text></svg>`;
}
function csv(name,rows){const text=rows.map(row=>row.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function invalidateSurvey(msg){current=[];$('surveyError').textContent=msg;$('surveyError').hidden=false;$('surveyMetrics').innerHTML='';$('trajectory').innerHTML='';$('surveyTable').innerHTML='';$('comparison').textContent='Current survey invalid; correct inputs before comparing with the saved baseline.';$('surveyQc').textContent='Results unavailable. Correct the survey inputs.';$('exportSurvey').disabled=true;}
function calcSurvey(){try{
 let vs=value('vs');if(vs<0||vs>=360)throw Error('Vertical section azimuth must be 0–<360°.');
 current=survey(parseSurvey($('stations').value),$('unit').value,{tvd:value('tvd'),n:value('north'),e:value('east')},value('limit'));
 $('surveyError').hidden=true;$('exportSurvey').disabled=false;let last=current.at(-1),first=current[0],u=$('unit').value,ref=u==='m'?'°/30 m':'°/100 ft',max=Math.max(...current.map(r=>r.dls)),closure=Math.hypot(last.n-first.n,last.e-first.e),warnings=current.filter((r,i)=>i&&r.dls>value('limit')).length;
 $('surveyMetrics').innerHTML=metric('Final TVD',fmt(last.tvd),u)+metric('Horizontal closure',fmt(closure),u,'from tie-in')+metric('Maximum DLS',fmt(max,2),ref)+metric('Final MD',fmt(last.md),u,`${current.length} stations`);
 $('surveyTable').innerHTML='<thead><tr>'+['MD '+u,'Inc °','Azi °','TVD '+u,'North '+u,'East '+u,'DLS '+ref,'RF'].map(s=>`<th>${s}</th>`).join('')+'</tr></thead><tbody>'+current.map((r,i)=>`<tr class="${r.dls>value('limit')?'warn':''}">${[r.md,r.inc,r.azi,r.tvd,r.n,r.e,i?r.dls:null,r.rf].map((n,j)=>`<td>${n===null?'—':fmt(n,j===7?6:2)}</td>`).join('')}</tr>`).join('')+'</tbody>';
 $('surveyQc').textContent=`${warnings?`${warnings} interval(s) exceed the user-defined DLS review threshold.`:'No interval exceeds the user-defined DLS review threshold.'} Zero-inclination azimuth does not affect position. No magnetic/grid correction or anti-collision analysis is applied.`;drawTrajectory();
 }catch(e){invalidateSurvey(e.message);}}
function drawTrajectory(){if(!current.length)return;let u=$('unit').value,first=current[0],vs=value('vs')*rad,points,options,caption;
 $('rotationLabel').hidden=view!=='3d';$('cameraControls').hidden=view!=='3d';
 if(baseline){let b=baseline.rows.at(-1),r=current.at(-1),factor=baseline.unit===u?1:baseline.unit==='m'?1/.3048:.3048;$('comparison').textContent=`Baseline endpoint difference (current − saved): TVD ${fmt(r.tvd-b.tvd*factor,2)} ${u}; North ${fmt(r.n-b.n*factor,2)} ${u}; East ${fmt(r.e-b.e*factor,2)} ${u}. This is a trajectory comparison, not clearance or anti-collision analysis.`;}
 if(view==='3d'){let saved=baseline?baseline.rows.map(r=>{let f=baseline.unit===u?1:baseline.unit==='m'?1/.3048:.3048;return {...r,e:r.e*f,n:r.n*f,tvd:r.tvd*f};}):[];$('trajectory').innerHTML=trajectory3d(current,saved,{azimuth:value('rotation'),elevation:value('elevation'),zoom:value('zoom'),unit:u});$('plotCaption').textContent='Interactive orthographic 3D: drag to orbit; use sliders or arrow keys to rotate and +/− to zoom. Blue: current; orange dashed: saved baseline. Equal scale in all three dimensions; lines join survey stations. Hover a station for coordinates.';return;}
 if(view==='section'){points=current.map(r=>[(r.n-first.n)*Math.cos(vs)+(r.e-first.e)*Math.sin(vs),r.tvd]);options={xlabel:'Vertical section ('+u+')',ylabel:'TVD ('+u+') · positive down',equal:true,down:true};caption='Section projected onto the selected azimuth. Equal horizontal/vertical scale; survey-station chords are shown.';}
 else if(view==='plan'){points=current.map(r=>[r.e,r.n]);options={xlabel:'East ('+u+')',ylabel:'North ('+u+')',equal:true};caption='Plan view. North up, East right; both axes use the same scale. Coordinates include the tie-in.';}
 else if(view==='dls'){points=current.slice(1).map(r=>[r.md,r.dls]);options={xlabel:'MD ('+u+')',ylabel:'DLS ('+(u==='m'?'°/30 m':'°/100 ft')+')',zero:true};caption='DLS belongs to the interval ending at each station. Dashed line: your review threshold.';}
 else{let a=value('rotation')*rad;points=current.map(r=>{let n=r.n-first.n,e=r.e-first.e,z=r.tvd-first.tvd;return [e*Math.cos(a)-n*Math.sin(a),z*.866+(e*Math.sin(a)+n*Math.cos(a))*.5];});options={xlabel:'Rotated horizontal coordinate ('+u+')',ylabel:'Projected depth coordinate ('+u+')',equal:true,down:true};caption='Orthographic 3D projection, 30° view elevation. Rotate to inspect survey-station geometry; projected depth is not TVD.';}
 let series=[{points,dots:true}];if(view==='dls')series.push({points:[[points[0][0],value('limit')],[points.at(-1)[0],value('limit')]],color:'#c46b16',dash:true});$('trajectory').innerHTML=chart(series,options);$('plotCaption').textContent=caption;
}
function loadExample(){let rows=example(),type=$('profile').value;rows=rows.map((r,k)=>({...r,inc:type==='vertical'?0:type==='s'&&k>17?Math.max(0,60-(k-17)*5):r.inc,azi:type==='turn'&&k>17?45+(k-17)*4:45}));if($('unit').value==='ft')rows=rows.map(r=>({...r,md:r.md/.3048}));$('stations').value=rows.map(r=>[r.md.toFixed(4),r.inc,r.azi].join(', ')).join('\n');for(let k of ['tvd','north','east'])$(k).value=0;calcSurvey();}
const specs={flowInputs:[['q','Flow rate · L/min',1500,50,4000,50],['rho','Mud density · kg/m³',1200,800,2400,10]],rheoInputs:[['K','K · Pa·sⁿ',.25,.001,5,.01],['n','Flow index n',.65,.4,1,.05]],geometryInputs:[['L','Total fluid path · m',3000,10,12000,100],['bhaL','BHA length · m',150,0,1000,10],['D','Drill pipe ID · mm',100,30,200,1],['bhaD','BHA ID · mm',70,20,200,1]],restrictionInputs:[['cd','Nozzle Cd',.95,.1,1,.01],['pcd','Pulser Cd',.8,.1,1,.01],['open','Open area · mm²',1800,10,10000,50],['closed','Restricted area · mm²',1400,10,10000,50]],signalInputs:[['gas','Local gas · vol %',0,0,5,.1],['pressure','Pressure · MPa abs',10,.1,100,1],['bulk','Liquid bulk K · GPa',2.2,.1,5,.1],['freq','Frequency · Hz',1,.1,10,.1],['alpha','Base loss · dB/km',2,0,30,.5],['gasPenalty','Gas loss coefficient¹',3,0,30,.5],['noise','Noise RMS · psi',5,.1,50,.5]]};
for(let [id,rows]of Object.entries(specs))$(id).innerHTML=rows.map(([key,label,v,min,max,step])=>`<label>${label}<input id="${key}" type="number" value="${v}" min="${min}" max="${max}" step="${step}"></label>`).join('');
$('signalInputs').insertAdjacentHTML('afterend','<p class="hint">¹ dB/km per gas percentage point at 1 Hz and 100 mm ID. Hypothetical sensitivity coefficient.</p>');
function inputs(){let p={};for(let rows of Object.values(specs))for(let [key,,v,min,max]of rows){p[key]=value(key);if(p[key]<min||p[key]>max)throw Error(`${key}: allowed study range ${min}–${max}.`);}p.nozzles=$('nozzles').value.split(',').map(s=>s.trim()===''?NaN:Number(s));if(p.nozzles.length>12||p.nozzles.some(d=>d<1||d>32))throw Error('Enter 1–12 nozzle sizes, each 1–32 (1/32 inch), separated by commas.');if($('rheology').value==='newton')p.n=1;return p;}
function calcHyd(){try{let p=inputs(),h=hydraulics(p),s=telemetry(p,h);hydState={p,h,s};drawSweep();$('hydError').hidden=true;$('exportHyd').disabled=false;
 $('hydMetrics').innerHTML=metric('Internal loss · open',fmt(h.total/psi,0),'psi','partial system')+metric('Bit nozzle loss',fmt(h.bit/psi,0),'psi')+metric('Restriction increment',fmt(h.pulse/psi,1),'psi','source scale')+metric('Total flow area',fmt(h.area/0.00064516,3),'in²');
 let losses=[['Drill pipe',h.dp.dp],['BHA bore',h.bha.dp],['Bit nozzles',h.bit],['Pulser · open',h.open]];let max=Math.max(...losses.map(r=>r[1]));$('pressureBars').innerHTML=losses.map(([label,v])=>`<div class="barrow"><span>${label}</span><div class="track"><div class="bar" style="width:${v/max*100}%"></div></div><b>${fmt(v/psi,1)} psi</b></div>`).join('');
 $('hydDetails').innerHTML=`<span>Drill pipe: Reɢ ${fmt(h.dp.re,0)} · fᴰ ${fmt(h.dp.fd,4)}<br>${h.dp.regime}</span><span>BHA: Reɢ ${fmt(h.bha.re,0)} · fᴰ ${fmt(h.bha.fd,4)}<br>${h.bha.regime}</span><span>Mean jet velocity: ${fmt(h.jet)} m/s</span><span>Restricted-state internal loss: ${fmt(h.restricted/psi,0)} psi</span>`;
 let clean=[],noisy=[],duration=4/p.freq;for(let i=0;i<=700;i++){let t=i/700*duration,a=s.surface/psi*Math.sin(2*Math.PI*p.freq*(t-s.delay)),noise=p.noise*(Math.sin(2*Math.PI*3*p.freq*t+.3)+Math.sin(2*Math.PI*7*p.freq*t+1.2));clean.push([t,a]);noisy.push([t,a+noise]);}
 $('wave').innerHTML=chart([{points:noisy,color:'#9aaebd',width:1.5},{points:clean,color:'#1168b2',width:2}],{xlabel:'Time (s) · steady-state received signal',ylabel:'AC pressure (psi)',height:260});
 $('signalMetrics').innerHTML=metric('Surface amplitude',fmt(s.surface/psi,2),'psi peak · assumed')+metric('Channel loss',fmt(s.loss,1),'dB · assumed law')+metric('Acoustic travel time',fmt(s.delay,2),'s · uniform fluid')+metric('SNR',fmt(s.snr,1),'dB · illustrative');
 let attenuation=Array.from({length:101},(_,i)=>{let x=p.L*i/100;return [x,h.pulse/psi*10**(-s.lossPerKm*x/1000/20)];});$('attenuation').innerHTML=chart([{points:attenuation}],{xlabel:'Travel distance from pulser (m)',ylabel:'Assumed amplitude (psi peak)',zero:true,height:260});
 $('signalNote').textContent=`Wave speed ${fmt(s.c,0)} m/s; effective ID ${fmt(s.effectiveD*1000,1)} mm; assumed attenuation ${fmt(s.lossPerKm,2)} dB/km. A lower surface amplitude does not alone establish whether data can be decoded.`;
 $('hydQc').textContent=(h.dp.re>2100&&h.dp.re<4000||h.bha.re>2100&&h.bha.re<4000?'Transition regime: pressure losses use interpolation. ':'')+(Math.max(h.dp.re,h.bha.re)>100000?'High generalized Reynolds number: extrapolation beyond a conservative study range. ':'')+'No field data calibration. Real mud yield stress, roughness, multiphase hydraulics and transient restrictions require more complete models.';
 }catch(e){hydState=null;sweepRows=[];for(let id of ['sweepPressure','sweepSignal'])$(id).innerHTML='';$('exportSweep').disabled=true;$('hydError').hidden=false;$('hydError').textContent=e.message;$('exportHyd').disabled=true;for(let id of ['hydMetrics','pressureBars','hydDetails','wave','signalMetrics','attenuation','signalNote'])$(id).innerHTML='';$('hydQc').textContent='Results unavailable. Correct the input values.';}}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==b.dataset.tab);document.querySelectorAll('.tab').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-pressed',String(t===b));});});
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('selected',x===b));drawTrajectory();});
$('calculate').onclick=calcSurvey;$('load').onclick=loadExample;$('rotation').oninput=drawTrajectory;
for(let id of ['stations','limit','tvd','north','east','vs'])$(id).addEventListener('input',calcSurvey);
$('unit').onchange=()=>{try{let rows=parseSurvey($('stations').value),factor=oldUnit==='m'?1/.3048:.3048;$('stations').value=rows.map(r=>[r.md*factor,r.inc,r.azi].join(', ')).join('\n');for(let id of ['tvd','north','east'])$(id).value=value(id)*factor;$('limit').value=value('limit')*($('unit').value==='ft'?30.48/30:30/30.48);oldUnit=$('unit').value;calcSurvey();}catch(e){$('unit').value=oldUnit;invalidateSurvey(e.message);}};
$('exportSurvey').onclick=()=>{if(!current.length)return;const u=$('unit').value;csv('MWD_Survey_'+u+'.csv',[[`MD_${u}`,'Inclination_deg','Azimuth_deg',`TVD_${u}`,`North_${u}`,`East_${u}`,u==='m'?'DLS_deg_per_30m':'DLS_deg_per_100ft','Dogleg_deg','Ratio_factor'],...current.map((r,i)=>[r.md,r.inc,r.azi,r.tvd,r.n,r.e,i?r.dls:'',r.beta,r.rf])]);};
document.querySelectorAll('#hyd input').forEach(x=>x.addEventListener('input',calcHyd));
$('rheology').onchange=()=>{let isN=$('rheology').value==='newton';$('n').disabled=isN;$('n').value=isN?1:.65;$('K').value=isN?.03:.25;$('K').parentElement.firstChild.textContent=isN?'Viscosity μ · Pa·s':'K · Pa·sⁿ';calcHyd();};
$('resetHyd').onclick=()=>{for(let rows of Object.values(specs))for(let [k,,v] of rows)$(k).value=v;$('rheology').value='power';$('n').disabled=false;$('K').parentElement.firstChild.textContent='K · Pa·sⁿ';$('nozzles').value='12,12,12';calcHyd();};
$('exportHyd').onclick=()=>{if(!hydState)return;let {p,h,s}=hydState;csv('MWD_Hydraulics_Telemetry_Study.csv',[['Parameter','Value','Unit / basis'],['Study','Synthetic; uncalibrated; not a field program',''],...Object.entries(p).map(([k,v])=>[k,Array.isArray(v)?v.join(';'):v,({q:'L/min',rho:'kg/m3',L:'m',bhaL:'m',D:'mm',bhaD:'mm',K:'Pa.s^n',n:'dimensionless',cd:'dimensionless',pcd:'dimensionless',open:'mm2',closed:'mm2',nozzles:'1/32 inch',gas:'local vol %',pressure:'MPa absolute',bulk:'GPa',freq:'Hz',alpha:'dB/km at 1Hz and 100mm ID',gasPenalty:'dB/km per gas percentage point',noise:'psi RMS'})[k]]),['Internal open loss',h.total/psi,'psi; partial system'],['Bit loss',h.bit/psi,'psi'],['Pulse increment',h.pulse/psi,'psi'],['Wave speed',s.c,'m/s; homogeneous rigid pipe'],['Channel loss',s.loss,'dB; hypothetical attenuation'],['Surface amplitude',s.surface/psi,'psi peak; assumed'],['SNR',s.snr,'dB; sinusoidal RMS/noise RMS']]);};
loadExample();calcHyd();fetch('verification.json').then(r=>r.json()).then(r=>{$('testSummary').textContent=`Calculation checks: ${r.passed} automated assertions passed. Coverage: ${r.coverage}. These checks verify implementation and analytical cases, not field accuracy.`;}).catch(()=>{$('testSummary').textContent='Verification details unavailable.';});

function drawSweep(){if(!hydState)return;let key=$('sweepParameter').value,{p}=hydState;let ranges={q:[50,4000,'Flow rate (L/min)'],gas:[0,5,'Local gas (vol %)'],freq:[.1,10,'Frequency (Hz)'],L:[Math.max(10,p.bhaL+1),12000,'Fluid path (m)']},[low,high,label]=ranges[key];sweepRows=sensitivity(p,key,low,high);$('sweepPressure').innerHTML=chart([{points:sweepRows.map(r=>[r.value,r.internalPsi])}],{xlabel:label,ylabel:'Open internal loss (psi) · partial system',zero:true,height:260});$('sweepSignal').innerHTML=chart([{points:sweepRows.map(r=>[r.value,r.surfacePsi]),color:'#c46b16'}],{xlabel:label,ylabel:'Assumed surface amplitude (psi peak)',zero:true,height:260});$('exportSweep').disabled=false;}
$('sweepParameter').onchange=drawSweep;
$('exportSweep').onclick=()=>{if(sweepRows.length)csv('MWD_Sensitivity.csv',[['Varied input',$('sweepParameter').value],['Basis','Other inputs held at current study; hypothetical telemetry law'],...Object.entries(hydState.p).map(([k,v])=>['Fixed / base input '+k,Array.isArray(v)?v.join(';'):v]),['Value','Internal_open_psi','Surface_peak_psi','SNR_dB','Travel_time_s'],...sweepRows.map(r=>[r.value,r.internalPsi,r.surfacePsi,r.snr,r.delay])]);};
$('saveBaseline').onclick=()=>{if(!current.length)return;baseline={rows:current.map(r=>({...r})),unit:$('unit').value};drawTrajectory();};
$('clearBaseline').onclick=()=>{baseline=null;$('comparison').textContent='Save a baseline, then change the survey to compare endpoints.';drawTrajectory();};
for(let id of ['elevation','zoom'])$(id).oninput=drawTrajectory;
$('resetCamera').onclick=()=>{$('rotation').value=30;$('elevation').value=30;$('zoom').value=1;drawTrajectory();};
let drag=null;
$('trajectory').addEventListener('pointerdown',e=>{if(view!=='3d')return;drag={x:e.clientX,y:e.clientY,a:value('rotation'),b:value('elevation')};$('trajectory').setPointerCapture(e.pointerId);});
$('trajectory').addEventListener('pointermove',e=>{if(!drag)return;$('rotation').value=((drag.a+(e.clientX-drag.x)*.5)%360+360)%360;$('elevation').value=Math.max(-80,Math.min(80,drag.b-(e.clientY-drag.y)*.5));drawTrajectory();});
for(let event of ['pointerup','pointercancel'])$('trajectory').addEventListener(event,()=>drag=null);
$('trajectory').addEventListener('keydown',e=>{if(view!=='3d')return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-'].includes(e.key)){e.preventDefault();if(e.key.startsWith('Arrow')){let id=['ArrowLeft','ArrowRight'].includes(e.key)?'rotation':'elevation';$(id).value=Number($(id).value)+(['ArrowLeft','ArrowDown'].includes(e.key)?-5:5);}else $('zoom').value=Number($('zoom').value)+(e.key==='+'?.1:-.1);drawTrajectory();}});
